from statsmodels.tsa.arima.model import ARIMA

def aic_grid(x, max_p, max_q):
    grid = {}
    for p in range(max_p + 1):
        for q in range(max_q + 1):
            res = ARIMA(x, order=(p, 0, q)).fit()
            grid[(p, q)] = round(res.aic, 2)
    return grid

